import { useQuery, type UseQueryOptions } from "@tanstack/react-query";
import { listRewardHistoryHandler } from "../handlers/listRewardHistoryHandler";
import type { ApiError } from "../runtime/client";

type Data = Awaited<ReturnType<typeof listRewardHistoryHandler>>;

export function useListRewardHistory(
  username: string,
  bookmark?: string | null,
  options?: Omit<UseQueryOptions<Data, ApiError>, "queryKey" | "queryFn">,
) {
  return useQuery<Data, ApiError>({
    queryKey: ["listRewardHistory", username, bookmark],
    queryFn: () => listRewardHistoryHandler(username, bookmark),
    ...options,
  });
}
